predicate IsEven(n: int)
{
    n % 2 == 0
}

method IsProductEven(arr: array<int>) returns (result: bool)
    ensures result <==> exists i :: 0 <= i < arr.Length && IsEven(arr[i])
{
    result := false;
    var i := 0;
    while i < arr.Length
        invariant 0 <= i <= arr.Length
        invariant result <==> exists k :: 0 <= k < i && IsEven(arr[k])
    {
        if IsEven(arr[i]) {
            result := true;
            // No need to continue checking once an even number is found
            break;
        }
        i := i + 1;
    }
}

